#[test]
fn radius_and_score_follow_the_kind() {
    let pos = Vec2::new(100.0, 100.0);
    let large = Asteroid::new(AsteroidKind::Large, pos, Vec2::ZERO);
    let medium = Asteroid::new(AsteroidKind::Medium, pos, Vec2::ZERO);
